before.default:
final radius = 0;
final theme = light;
render(scene);

after.default:
final radius = 16;
final theme = inherited;
render(scene);

props.after:
final radius = 24;
final theme = custom;
render(scene);

lines.default:
final theme = VideoStyle(
  background: canvas,
  foreground: ink,
  surface: panel,
  accent: highlight,
);
render(theme);

text.default:
final seconds = frame / fps;
final progress = cueProgress(
  seconds, start, end,
);
